with flattened_attrs as (select id, service, host, log_ts, level, latency_ms, status_code, payload_json, context, context['version'] as version, coalesce(context['version'], 'direct') as version_or_default from app_logs) select *, row_number() over (order by status_code, id) row_seq, row_number() over (partition by service, host order by status_code, id) seq_no from flattened_attrs
